import { useLanguage } from './LanguageContext';
import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { Activity, ArrowDown, ArrowRight, ArrowUp, ArrowUpRight, Bell, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, CloudRain, CloudSun, Download, Droplets, ExternalLink, Info, LayoutDashboard, LifeBuoy, Languages, MapPin, Menu, Search, RefreshCw, Settings2, ShieldCheck, SlidersHorizontal, Sun, TriangleAlert, Waves, Wind, X } from 'lucide-react';
import { DEFAULT_PREFERENCES, dayKey, getWindows, highestRisk, riskFor, sumRain, TIME_ZONE } from '../shared/model';
import type { Advisory, DashboardData, Hour, Preferences, Risk, RiskWindow } from '../shared/types';
import ForecastChart from './components/ForecastChart';
import CoastalArt from './components/CoastalArt';
import FloodCheck from './components/FloodCheck';
import { DEFAULT_ZIP, readStored, writeStored, storageKey, readPreferences, readChecklist } from './preferences';
import { MobileHourlyList, MobileTideList } from './components/MobileForecastRows';

const LocalMap = lazy(() => import('./components/LocalMap'));
type Page = 'overview' | 'tides' | 'rainfall' | 'risk' | 'calendar' | 'prepare' | 'settings';
type Modal = 'alerts' | 'methodology' | 'advisory' | null;
const navItems = [
  { id: 'overview', name: 'Overview', icon: LayoutDashboard }, { id: 'tides', name: 'Tide forecast', icon: Waves },
  { id: 'rainfall', name: 'Rainfall forecast', icon: CloudRain }, { id: 'risk', name: 'Overlap outlook', icon: Activity },
  { id: 'calendar', name: 'King tide calendar', icon: CalendarDays },
] as const;
const mobileNames = { overview: 'Home', tides: 'Tides', rainfall: 'Rain', risk: 'Outlook', calendar: 'Calendar' };
const pageTitles: Record<Page, string> = { overview: 'Your coastal outlook', tides: 'Tide forecast', rainfall: 'Rainfall forecast', risk: 'Tide & rain outlook', calendar: 'King tide calendar', prepare: 'Be prepared', settings: 'Settings & alerts' };
const pageDescriptions: Record<Page, string> = { overview: 'Tides, rainfall, and a little foresight. All in one place.', tides: 'Highs, lows, and the windows in between. Plan around the water.', rainfall: 'See when rain is expected and how much could fall.', risk: 'Spot the windows when higher tides and rainfall may overlap.', calendar: 'Keep an eye on the season’s higher-than-usual tides.', prepare: 'Simple steps to help your household stay ahead of coastal flooding.', settings: 'Adjust your planning thresholds and on-device notifications.' };
const riskNames: Record<Risk, string> = { low: 'Low', moderate: 'Elevated', high: 'High', unknown: 'Incomplete' };
const checklist = [
  { id: 'vehicles', title: 'Move vehicles to higher ground', text: 'Plan a parking spot away from low-lying streets before high tide.' },
  { id: 'drains', title: 'Check accessible storm drains', text: 'Remove loose leaves and debris safely before rain arrives.' },
  { id: 'belongings', title: 'Protect low-level belongings', text: 'Raise valuables and outdoor equipment above potential floodwater.' },
  { id: 'routes', title: 'Plan an alternate route', text: 'Avoid flooded streets. Never walk or drive through standing water.' },
  { id: 'kit', title: 'Keep an essentials kit ready', text: 'Charge devices and keep medications, drinking water, and a flashlight handy.' },
  { id: 'updates', title: 'Check official advisories', text: 'Review the latest National Weather Service and City of Hollywood updates.' },
];
function initialZip(): string { const value = new URLSearchParams(location.search).get('zip'); return value && /^\d{5}$/.test(value) ? value : DEFAULT_ZIP; }
function Badge({ risk, children }: { risk: Risk; children?: React.ReactNode }) { const { t } = useLanguage(); return <span className={`risk-badge ${risk}`}><span/>{children ?? t('{risk} overlap', { risk: t(riskNames[risk]) })}</span>; }
function WeatherIcon({ chance, size = 26 }: { chance: number | null; size?: number }) { return chance !== null && chance >= 40 ? <CloudRain size={size} className="weather-rain"/> : chance !== null && chance >= 20 ? <CloudSun size={size} className="weather-sun"/> : <Sun size={size} className="weather-sun"/>; }
function PanelHeading({ title, subtitle, children }: { title: string; subtitle?: string; children?: React.ReactNode }) { return <div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{children}</div>; }

export default function App() {
  const { language, setLanguage, t, formatDay, formatTime, describeWeather } = useLanguage();
  const [page, setPage] = useState<Page>(() => { const p = location.hash.slice(1); return p in pageTitles ? p as Page : 'overview'; });
  const [activeZip, setActiveZip] = useState(initialZip);
  const [zipDraft, setZipDraft] = useState(initialZip);
  const [searchError, setSearchError] = useState('');
  const zipInput = useRef<HTMLInputElement>(null);
  const activeZipRef = useRef(activeZip);
  const requestVersion = useRef(0);
  const requestController = useRef<AbortController | null>(null);
  const [storageAvailable, setStorageAvailable] = useState(true);
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [now, setNow] = useState(Date.now());
  const [preferences, setPreferences] = useState<Preferences>(() => readPreferences(activeZip));
  const [completed, setCompleted] = useState<string[]>(() => readChecklist(activeZip));
  const [horizon, setHorizon] = useState(24);
  const [selectedDay, setSelectedDay] = useState<string | null>(null);
  const [modal, setModal] = useState<Modal>(null);
  const [advisory, setAdvisory] = useState<Advisory | null>(null);
  const [mobileNav, setMobileNav] = useState(false);
  const [toast, setToast] = useState('');
  const [dateOpen, setDateOpen] = useState(false);

  const dialog = useRef<HTMLDialogElement>(null);
  const menuDialog = useRef<HTMLDialogElement>(null);

  async function refresh(zip = activeZipRef.current, search = false) {
    const version = ++requestVersion.current;
    requestController.current?.abort();
    const controller = new AbortController(); requestController.current = controller;
    const timeout = setTimeout(() => controller.abort(), 65000);
    setLoading(true); if (search) setSearchError('');
    try {
      const response = await fetch(`/api/dashboard?zip=${encodeURIComponent(zip)}`, { signal: controller.signal });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error ?? 'The forecast is temporarily unavailable. Please try again.');
      if (version !== requestVersion.current) return;
      if (result.location?.zip !== zip) throw new Error('The forecast location could not be confirmed. Please try again.');
      if (zip !== activeZipRef.current) {
        setPreferences(readPreferences(zip)); setCompleted(readChecklist(zip));
        setActiveZip(zip); activeZipRef.current = zip; setSelectedDay(null);
        setModal(null); setAdvisory(null); setDateOpen(false);
      }
      setData(result as DashboardData); setZipDraft(zip); setError(''); setSearchError('');
      const url = new URL(window.location.href);
      if (zip === DEFAULT_ZIP) url.searchParams.delete('zip'); else url.searchParams.set('zip', zip);
      history.replaceState(null, '', url);
    } catch (e) {
      if (version !== requestVersion.current) return;
      const message = controller.signal.aborted ? 'The forecast request timed out. Please try again.' : e instanceof Error ? e.message : 'Unable to connect to the forecast service.';
      if (search) { setSearchError(message); zipInput.current?.focus(); } else setError(message);
    } finally { clearTimeout(timeout); if (version === requestVersion.current) { setLoading(false); requestController.current = null; } }
  }
  function submitZip(event: React.FormEvent) {
    event.preventDefault();
    const zip = zipDraft.trim();
    if (!/^\d{5}$/.test(zip)) { setSearchError('Enter a five-digit US ZIP code, such as 33139.'); zipInput.current?.focus(); return; }
    void refresh(zip, true);
  }
  useEffect(() => {
    void refresh();
    const timer = setInterval(() => setNow(Date.now()), 60000);
    const updates = setInterval(() => { if (!requestController.current || requestController.current.signal.aborted) void refresh(); }, 10 * 60000);
    return () => { clearInterval(timer); clearInterval(updates); requestVersion.current++; requestController.current?.abort(); };
  }, []);
  useEffect(() => { const listener = () => { const p = location.hash.slice(1); setPage(p in pageTitles ? p as Page : 'overview'); setMobileNav(false); setDateOpen(false); }; window.addEventListener('hashchange', listener); return () => window.removeEventListener('hashchange', listener); }, []);
  useEffect(() => { setStorageAvailable(writeStored(storageKey('preferences', activeZip), preferences)); }, [preferences, activeZip]);
  useEffect(() => { writeStored(storageKey('checklist', activeZip), completed); }, [completed, activeZip]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (modal && dialog.current && !dialog.current.open) dialog.current.showModal(); else if (!modal) dialog.current?.close(); }, [modal]);
  useEffect(() => { if (mobileNav && menuDialog.current && !menuDialog.current.open) menuDialog.current.showModal(); else if (!mobileNav) menuDialog.current?.close(); }, [mobileNav]);

  useEffect(() => { document.title = data ? `Tidewatch · ${data.location.name} · ${activeZip}` : t('Tidewatch · Hollywood coastal outlook'); }, [data, activeZip, t]);

  const futureHours = useMemo(() => data?.hours.filter(h => Date.parse(h.time) + 3600000 > now) ?? [], [data, now]);
  const next24 = futureHours.slice(0, 24);
  const outlookRisk = highestRisk(next24, preferences);
  const windows = useMemo(() => getWindows(futureHours, preferences), [futureHours, preferences]);
  const nextHigh = data?.tides.find(t => t.type === 'H' && Date.parse(t.time) > now);
  const nextLow = data?.tides.find(t => t.type === 'L' && Date.parse(t.time) > now);
  const rain24 = sumRain(next24);
  const days = useMemo(() => {
    const grouped = new Map<string, Hour[]>();
    futureHours.forEach(h => { const key = dayKey(h.time); if (!grouped.has(key)) grouped.set(key, []); grouped.get(key)!.push(h); });
    return [...grouped].slice(0, 7).map(([key, hours]) => ({ key, hours, risk: highestRisk(hours, preferences), rain: sumRain(hours), chance: hours.some(h => h.chance !== null) ? Math.max(...hours.map(h => h.chance ?? 0)) : null, high: data?.tides.filter(t => t.type === 'H' && dayKey(t.time) === key).reduce((n, t) => Math.max(n, t.height), 0) ?? 0 }));
  }, [futureHours, preferences, data]);
  const chartHours = selectedDay ? futureHours.filter(h => dayKey(h.time) === selectedDay) : futureHours.slice(0, horizon);
  const allLive = !!data && Object.values(data.sources).every(s => s.status === 'live') && now - Date.parse(data.generatedAt) < 30 * 60000 && !error;
  const nextWindow = windows[0];
  const maximumThreshold = activeZip === DEFAULT_ZIP ? 4 : Math.min(40, Math.max(4, preferences.tideThreshold, Math.ceil(Math.max(...(data?.tides.map(t => t.height) ?? [0])) + 1)));

  useEffect(() => {
    if (!preferences.notifications || !data || !allLive || !('Notification' in window) || Notification.permission !== 'granted') return;
    const upcoming = windows.find(w => Date.parse(w.end) > now && Date.parse(w.start) - now <= preferences.leadHours * 3600000);
    if (!upcoming) return;
    const key = upcoming.start + ':' + upcoming.risk;
    if (readStored(storageKey('lastNotification', activeZip), '') === key) return;
    new Notification(t('Tidewatch · Tide and rain may overlap'), { body: t('{day} {start}–{end}. {risk} planning potential in {location} (ZIP {zip}).', { day: formatDay(upcoming.start), start: formatTime(upcoming.start), end: formatTime(upcoming.end), risk: t(riskNames[upcoming.risk]), location: data.location.name, zip: activeZip }), icon: '/brand/icon-192.png' });
    writeStored(storageKey('lastNotification', activeZip), key);
  }, [preferences, windows, now, data, allLive, activeZip, t, formatDay, formatTime]);

  function navigate(next: Page) { setPage(next); location.hash = next; setMobileNav(false); setDateOpen(false); setSelectedDay(null); window.scrollTo({ top: 0, behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' }); }
  function navigateLink(event: React.MouseEvent<HTMLAnchorElement>, next: Page) { if (event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) { event.preventDefault(); navigate(next); } }
  function toggleTask(id: string) { setCompleted(old => old.includes(id) ? old.filter(x => x !== id) : [...old, id]); }
  async function toggleNotifications() {
    if (preferences.notifications) { setPreferences(p => ({ ...p, notifications: false })); return; }
    if (!('Notification' in window)) { setToast('This browser does not support desktop notifications.'); return; }
    try { const result = await Notification.requestPermission(); if (result === 'granted') { setPreferences(p => ({ ...p, notifications: true })); setToast('Notifications enabled while Tidewatch is open.'); } else setToast('Notifications are blocked. Enable them in your browser’s site settings.'); } catch { setToast('Notifications require a secure browser connection.'); }
  }
  function exportForecast() {
    if (!data) return;
    const header = t('Time (UTC),Local time (America/New_York),Estimated tide (ft MLLW),Estimated rain (in/hr),Rain chance (%),Temperature (F),Overlap potential');
    const csv = [header, ...futureHours.map(h => [h.time, `"${formatDay(h.time)} ${formatTime(h.time)}"`, h.tide?.toFixed(3) ?? '', h.rain?.toFixed(4) ?? '', h.chance ?? '', h.temperature ?? '', t(riskNames[riskFor(h, preferences)])].join(','))].join('\r\n');
    const url = URL.createObjectURL(new Blob([language === 'es' ? '\uFEFF' + csv : csv], { type: 'text/csv;charset=utf-8;' }));
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = `tidewatch-${activeZip}-${dayKey(new Date(now))}.csv`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); setToast('Your forecast has been exported.');
  }
  function openAdvisory(a: Advisory) { setAdvisory(a); setModal('advisory'); }

  const settingsForm = <div className="settings-form">
    <div className="settings-intro"><SlidersHorizontal size={21}/><div><h3>{t("Your overlap thresholds")}</h3><p>{t("These are personal planning triggers, not official flood levels. Review the tide threshold for each location; local tidal ranges differ.")}</p></div></div>
    <label className="range-label"><span>{t("Higher tide threshold")} <b>{preferences.tideThreshold.toFixed(1)} ft MLLW</b></span><input type="range" min={activeZip === DEFAULT_ZIP ? 1.5 : 0} max={maximumThreshold} step="0.1" value={preferences.tideThreshold} onChange={e => setPreferences(p => ({ ...p, tideThreshold: Number(e.target.value) }))}/><small>{t("Higher tide + either rain trigger below = elevated overlap.")}</small></label>
    <label className="range-label"><span>{t("Hourly rainfall trigger")} <b>{preferences.rainThreshold.toFixed(2)} in</b></span><input type="range" min="0.01" max="0.5" step="0.01" value={preferences.rainThreshold} onChange={e => setPreferences(p => ({ ...p, rainThreshold: Number(e.target.value) }))}/></label>
    <label className="range-label"><span>{t("Rain probability trigger")} <b>{preferences.chanceThreshold}%</b></span><input type="range" min="10" max="90" step="5" value={preferences.chanceThreshold} onChange={e => setPreferences(p => ({ ...p, chanceThreshold: Number(e.target.value) }))}/></label>
    <div className="notification-setting"><div><b>{t("Browser notifications")}</b><p>{t("Notify this device while the dashboard is open.")}</p></div><button className={`toggle ${preferences.notifications ? 'on' : ''}`} role="switch" aria-checked={preferences.notifications} aria-label={t("Browser notifications")} onClick={() => void toggleNotifications()}><span/></button></div>
    <label className="select-setting"><span>{t("Notify ahead of an overlap window")}</span><select value={preferences.leadHours} onChange={e => setPreferences(p => ({ ...p, leadHours: Number(e.target.value) }))}><option value={1}>{t("1 hour before")}</option><option value={3}>{t("3 hours before")}</option><option value={6}>{t("6 hours before")}</option><option value={12}>{t("12 hours before")}</option></select></label>
    <div className="settings-bottom"><span><CheckCircle2 size={14}/> {storageAvailable ? t('Saved in this browser for ZIP {zip}', { zip: activeZip }) : t("Browser storage is unavailable; changes last for this visit")}</span><button className="text-button" onClick={() => { setPreferences({ ...DEFAULT_PREFERENCES }); setToast('Default planning thresholds restored.'); }}>{t("Reset defaults")}</button></div>
  </div>;

  const forecastPanel = (mode: 'combined' | 'tides' | 'rain' = 'combined', wide = false) => <section id="forecast-timeline" tabIndex={-1} className={`panel timeline-panel ${wide ? 'wide-chart' : ''}`}>
    <PanelHeading title={mode === 'tides' ? t("Tide timeline") : mode === 'rain' ? t("Hourly precipitation") : t("Tides & rainfall")} subtitle={selectedDay ? formatDay(chartHours[0]?.time ?? new Date(now)) : t('The next {period}, together.', { period: horizon === 168 ? t('7 days') : t('{hours} hours', { hours: horizon }) })}>
      <div className="segmented" aria-label={t("Forecast time range")}>{[24, 48, 168].map(value => <button key={value} className={!selectedDay && horizon === value ? 'active' : ''} aria-pressed={!selectedDay && horizon === value} aria-label={value === 168 ? t("Next 7 days") : t('Next {hours} hours', { hours: value })} onClick={() => { setHorizon(value); setSelectedDay(null); }}>{value === 168 ? t("7 days") : `${value}h`}</button>)}</div>
    </PanelHeading>
    <div className="chart-legend">{mode !== 'rain' && <span><i className="legend-line"/> {t("Tide height")} <small>ft MLLW</small></span>}{mode !== 'tides' && <span><i className="legend-bar"/> {t("Rainfall")} <small>in/hr</small></span>}<button aria-label={t("Learn about forecast methodology")} onClick={() => setModal('methodology')}><Info size={14}/></button></div>
    <ForecastChart hours={chartHours} preferences={preferences} mode={mode}/>
    <div className="chart-footnote"><Info size={13}/><span>{mode === 'rain' ? t("Rain amounts are distributed evenly across NWS forecast intervals.") : t("Tide curve estimated between NOAA high/low predictions.")} {t("All times Eastern.")}</span></div>
  </section>;

  const dailyForecast = <section className="daily-section"><div className="section-heading"><div><h2>{t("The week ahead")}</h2><span>{t("Your next seven days at a glance")}</span></div><button className="text-button" onClick={() => navigate('risk')}>{t("Explore outlook")} <ArrowRight size={14}/></button></div>
    <div className="daily-grid">{days.map((day, i) => <button key={day.key} className={`day-card ${selectedDay === day.key ? 'selected' : ''}`} aria-pressed={selectedDay === day.key} aria-label={t('View forecast for {day}. {risk} overlap potential.', { day: formatDay(day.hours[0].time), risk: t(riskNames[day.risk]) })} onClick={() => { setSelectedDay(day.key); if (!['overview', 'tides', 'rainfall'].includes(page)) { setPage('overview'); location.hash = 'overview'; } document.querySelector('.timeline-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }}>
      <div className="day-name">{i === 0 ? t("Today") : formatDay(day.hours[0].time, { weekday: 'short' })}<small>{formatDay(day.hours[0].time, { month: 'short', day: 'numeric' })}</small></div>
      <div className="day-weather"><WeatherIcon chance={day.chance}/><span>{day.chance ?? '—'}<small>%</small></span></div>
      <div className="day-tide"><Waves size={13}/>{day.high ? day.high.toFixed(1) : '—'} ft <span>{t("high")}</span></div>
      <span className={`day-risk ${day.risk}`}><i/>{t(riskNames[day.risk])}</span>
    </button>)}</div><p className="daily-note">{t("Today shows the remaining forecast. Rain icons indicate probability; labels describe tide-and-rain overlap.")}</p>
  </section>;

  const preparation = (full = false) => <section className={`panel prepare-panel ${full ? 'full-prepare' : ''}`}>
    <PanelHeading title={full ? t("Your household checklist") : t("Small steps. Better prepared.")} subtitle={full ? t('{completed} of {total} steps complete. Your progress stays on this device.', { completed: completed.length, total: checklist.length }) : t("A few things to do before the water rises.")}><span className="icon-surface"><ShieldCheck size={20}/></span></PanelHeading>
    <div className="checklist">{(full ? checklist : checklist.slice(0, 3)).map(task => <label className={`checklist-item ${completed.includes(task.id) ? 'done' : ''}`} key={task.id}><input type="checkbox" checked={completed.includes(task.id)} onChange={() => toggleTask(task.id)}/><span className="custom-check"><Check size={13}/></span><span><b>{t(task.title)}</b>{full && <small>{t(task.text)}</small>}</span></label>)}</div>
    {full ? <div className="progress-track"><span style={{ width: `${completed.length / checklist.length * 100}%` }}/></div> : <button className="text-button" onClick={() => navigate('prepare')}>{t("View preparation guide")} <ArrowRight size={14}/></button>}
  </section>;

  return <div className="app-shell">
    <a className="skip-link" href="#main-content" onClick={event => { event.preventDefault(); document.getElementById('main-content')?.focus(); }}>{t("Skip to forecast")}</a>
    <aside className="sidebar">
      <a className="brand" href="#overview" onClick={e => { e.preventDefault(); navigate('overview'); }}><span className="brand-mark"><img src="/brand/wave-broadwalk-mark.svg" alt="" width="35" height="35"/></span><span>tidewatch<span className="brand-dot">.</span></span></a>
      <div className="workspace-location"><span className="location-icon"><MapPin size={18}/></span><div><b>{data?.location.name ?? (activeZip === DEFAULT_ZIP ? "Hollywood Beach, FL" : `ZIP ${activeZip}`)}</b><small>{t("Forecast location ·")} {activeZip}</small></div><ChevronDown size={13}/></div>
      <div className="nav-label">{t("YOUR DASHBOARD")}</div>
      <nav aria-label={t("Main navigation")}>{navItems.map(item => <a key={item.id} href={`#${item.id}`} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={event => navigateLink(event, item.id)} aria-label={t(item.name)} aria-current={page === item.id ? 'page' : undefined}><item.icon size={18} aria-hidden="true"/>{t(item.name)}{item.id === 'risk' && windows.length > 0 && <span className="nav-count" aria-hidden="true">{windows.length}</span>}</a>)}</nav>
      <div className="nav-label tools-label">{t("STAY READY")}</div>
      <a href="#prepare" className={`nav-item ${page === 'prepare' ? 'active' : ''}`} onClick={event => navigateLink(event, 'prepare')} aria-current={page === 'prepare' ? 'page' : undefined}><ShieldCheck size={18} aria-hidden="true"/>{t("Preparation guide")}</a>
      <a href="#settings" className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={event => navigateLink(event, 'settings')} aria-current={page === 'settings' ? 'page' : undefined}><Settings2 size={18} aria-hidden="true"/>{t("Settings & alerts")}</a>
      <div className="sidebar-bottom"><div className="season-card"><span className="season-icon"><Sun size={21}/></span><span className="eyebrow">{t("A SEASON TO STAY AWARE")}</span><h3>{t("Higher tides.")}<br/>{t("A little extra care.")}</h3><p>{t("Keep an eye on the tide during the fall king tide season.")}</p><button onClick={() => navigate('calendar')}>{t("See the calendar")} <ArrowUpRight size={15}/></button><svg viewBox="0 0 190 55" aria-hidden="true"><path d="M-10 30Q15 10 40 30T90 30T140 30T190 30T240 30M-10 40Q15 20 40 40T90 40T140 40T190 40T240 40M-10 50Q15 30 40 50T90 50T140 50T190 50T240 50" fill="none" stroke="#b7c7a8"/></svg></div><button className="sidebar-help" onClick={() => setModal('methodology')}><CircleHelp size={17}/>{t("About the data")} <ArrowUpRight size={13}/></button><div className="sidebar-footer"><span className="mini-brand"><Waves size={15}/></span><div>{t("Built for your coast")}<small>{data?.location.name ?? `ZIP ${activeZip}`}</small></div></div></div>
    </aside>
    <div className="main-shell">
      <header className="topbar"><a className="mobile-brand" href="#overview" onClick={event => navigateLink(event, 'overview')} aria-label={t("Tidewatch home")}><img src="/brand/wave-broadwalk-mark.svg" width="36" height="36" alt=""/><span>tidewatch<span>.</span></span></a><div className="breadcrumb"><span>{data?.location.name ?? `ZIP ${activeZip}`}</span><ChevronRight size={13} aria-hidden="true"/><b>{t(navItems.find(i => i.id === page)?.name ?? (page === 'prepare' ? 'Preparation guide' : 'Settings'))}</b></div><div className="topbar-right"><span className="live-status"><i className={allLive ? '' : 'pending'}/>{allLive ? t("Live sources") : loading ? t("Connecting") : t("Check sources")}</span><button className="icon-button notification-button" aria-label={t("View alerts and notification settings")} onClick={() => setModal('alerts')}><Bell size={20}/>{!!data?.alerts.length && <span/>}</button><button className="mobile-menu icon-button" onClick={() => setMobileNav(true)} aria-label={t("Open navigation")}><Menu size={21}/></button><button className="language-toggle" onClick={() => setLanguage(language === 'en' ? 'es' : 'en')} aria-label={t(language === 'en' ? 'Switch to Spanish' : 'Switch to English')} title={t(language === 'en' ? 'Switch to Spanish' : 'Switch to English')} lang={language === 'en' ? 'es' : 'en'}><Languages size={16} aria-hidden="true"/><span className="language-full">{language === 'en' ? 'Español' : 'English'}</span><span className="language-short" aria-hidden="true">{language === 'en' ? 'ES' : 'EN'}</span></button></div></header>
      <main id="main-content" tabIndex={-1}>
        <div className="page-heading"><div><div className="page-eyebrow"><span/>{data?.location.name ?? (activeZip === DEFAULT_ZIP ? "Hollywood Beach, FL" : t("Forecast location"))} · {activeZip}</div><h1>{t(pageTitles[page])}</h1><p>{t(pageDescriptions[page])}</p></div><div className="heading-actions"><div className="date-control"><button className="button secondary date-button" onClick={() => setDateOpen(v => !v)} aria-expanded={dateOpen}><CalendarDays size={15}/>{selectedDay && chartHours[0] ? formatDay(chartHours[0].time, { month: 'short', day: 'numeric' }) : formatDay(new Date(now), { month: 'short', day: 'numeric', year: 'numeric' })}<ChevronDown size={13}/></button>{dateOpen && <div className="date-dropdown"><b>{t("Select a forecast day")}</b><button onClick={() => { setSelectedDay(null); setDateOpen(false); }}>{t("Next 24 hours")}</button>{days.map(day => <button key={day.key} onClick={() => { setSelectedDay(day.key); setDateOpen(false); if (!['overview', 'tides', 'rainfall'].includes(page)) { setPage('overview'); location.hash = 'overview'; } }}>{formatDay(day.hours[0].time)}<Badge risk={day.risk}>{t(riskNames[day.risk])}</Badge></button>)}</div>}</div><button className="button primary" onClick={() => setModal('alerts')}><Bell size={15}/>{t("Set up alerts")}</button></div></div>
        <FloodCheck key={activeZip} zip={activeZip} activeTideThreshold={preferences.tideThreshold}/>
        <section className="location-search" aria-label={t("Choose forecast location")}>
          <form onSubmit={submitZip} noValidate>
            <label htmlFor="zip-search">{t("Find your local outlook")}</label>
            <div className="zip-search-controls"><div className="zip-input"><Search size={19} aria-hidden="true"/><input ref={zipInput} id="zip-search" name="zip" type="text" inputMode="numeric" autoComplete="postal-code" spellCheck={false} maxLength={5} placeholder={t("ZIP code, e.g. 33139…")} value={zipDraft} onChange={event => { setZipDraft(event.target.value); setSearchError(''); }} aria-invalid={!!searchError} aria-describedby="zip-help"/></div><button className="button primary" type="submit" disabled={loading}>{loading ? <RefreshCw size={17} className="spin" aria-hidden="true"/> : <ArrowRight size={17} aria-hidden="true"/>}<span>{loading ? t("Loading…") : t("Search")}</span></button></div>
          </form>
          <div id="zip-help" className={searchError ? 'zip-error' : 'zip-help'} role="status">{searchError ? t(searchError) : t('Viewing {location} · {zip}. Preferences stay in this browser for each ZIP.', { location: data?.location.name ?? (activeZip === DEFAULT_ZIP ? "Hollywood Beach, FL" : "ZIP " + activeZip), zip: activeZip })}</div>
          {activeZip !== DEFAULT_ZIP && <button className="text-button default-location" disabled={loading} onClick={() => void refresh(DEFAULT_ZIP, true)}><MapPin size={14} aria-hidden="true"/>{t("Back to Hollywood · 33019")}</button>}
        </section>
        {error && <div className="error-banner" role="alert"><TriangleAlert size={18}/><span>{t(error)}{data ? t(" Showing the last successful forecast; check its timestamps below.") : ''}</span><button onClick={() => void refresh()}>{t("Try again")}</button></div>}
        {data && activeZip !== DEFAULT_ZIP && <div className="station-reference"><Waves size={16} aria-hidden="true"/><span>{data.location.station ? t('Tide reference: {stationName} · NOAA {station} · {distance} km from the ZIP point. Local waterways may differ.', { stationName: data.location.stationName ?? '', station: data.location.station, distance: data.location.stationDistanceKm ?? '—' }) : t("No NOAA tide prediction station within 25 km. Rainfall forecasts remain available; tide overlap is incomplete.")} {t("All times Eastern.")}</span></div>}
        {data && !allLive && !loading && !error && <div className="error-banner"><Info size={18}/><span>{t("Some source data is cached or unavailable. Incomplete periods are marked; review data status below.")}</span><button onClick={() => void refresh()}>{t("Refresh")}</button></div>}
        {!data ? <div className="loading-state"><div className="loading-waves"><img src="/brand/wave-broadwalk-mark.svg" alt={t("Tidewatch wave and Broadwalk mark")} width="60" height="60"/></div><h2>{loading ? t("Gathering your coastal outlook") : t("Let’s reconnect to your coast")}</h2><p>{loading ? t("Bringing NOAA tides and National Weather Service forecasts together.") : t("The data providers could not be reached. Your forecast will appear once the connection is restored.")}</p>{!loading && <button className="button primary" onClick={() => void refresh()}><RefreshCw size={16}/>{t("Retry connection")}</button>}<div className="skeleton-grid">{[1, 2, 3, 4].map(i => <div key={i} className="skeleton-card"/>)}</div></div> : <>

        {page === 'overview' && <>
          <section className={`welcome-banner outlook-${outlookRisk}`}><div className="welcome-copy"><span className="eyebrow"><Clock3 size={14} aria-hidden="true"/>{t("YOUR NEXT 24 HOURS")}</span><Badge risk={outlookRisk}/><h2>{outlookRisk === 'unknown' ? t("A few gaps in the forecast.") : outlookRisk === 'low' ? t("A quieter coastal outlook.") : t("Keep an eye on tide & rain.")}</h2><p>{outlookRisk === 'unknown' ? t("Check official advisories while forecast data is incomplete.") : outlookRisk === 'low' ? t("No tide-and-rain overlap above your planning thresholds.") : t("Higher tides and rainfall may coincide. Plan a little ahead.")}</p><a href="#risk" onClick={event => navigateLink(event, 'risk')}>{t("View overlap windows")} <ArrowUpRight size={17} aria-hidden="true"/></a></div><CoastalArt/></section>
          {data.alerts.length > 0 && <button className="advisory-banner" onClick={() => openAdvisory(data.alerts.find(a => a.event.includes('Advisory')) ?? data.alerts[0])}><span className="advisory-symbol"><TriangleAlert size={17}/></span><span><b>{data.alerts.find(a => a.event.includes("Advisory"))?.event ?? data.alerts[0].event}</b><span>{data.alerts.find(a => a.event.includes("Advisory"))?.headline ?? data.alerts[0].headline}</span></span><span className="advisory-link">{t("View advisory")} <ArrowRight size={14}/></span></button>}
          <div className="metrics-grid"><section className="metric-card"><div className="metric-label"><span>{t("Next high tide")}</span><span className="metric-icon green"><Waves size={18}/></span></div><div className="metric-value">{nextHigh?.height.toFixed(2) ?? '—'}<small>ft</small><span className="value-tag">MLLW</span></div><div className="metric-detail"><Clock3 size={12}/>{nextHigh ? `${formatTime(nextHigh.time)} · ${dayKey(nextHigh.time) === dayKey(new Date(now)) ? t("Today") : formatDay(nextHigh.time, { weekday: 'short' })}` : t("Prediction unavailable")}</div></section>
          <section className="metric-card"><div className="metric-label"><span>{t("Rainfall outlook")}</span><span className="metric-icon blue"><CloudRain size={18}/></span></div><div className="metric-value">{rain24?.toFixed(2) ?? '—'}<small>in</small></div><div className="metric-detail"><span className="detail-dot blue"/>{t("Expected over the next 24 hours")}</div></section>
          <section className="metric-card"><div className="metric-label"><span>{t("Overlap potential")}</span><span className="metric-icon amber"><Activity size={18}/></span></div><div className={`metric-value text-value ${outlookRisk}`}>{t(riskNames[outlookRisk])}<span className={`metric-trend ${outlookRisk}`}><ArrowUpRight size={16}/></span></div><div className="metric-detail">{outlookRisk === 'unknown' ? t("Some forecast data is missing") : outlookRisk === 'low' ? t("No overlap above your thresholds") : t("High tide and rain may coincide")}</div></section>
          <section className="metric-card"><div className="metric-label"><span>{t("Next overlap window")}</span><span className="metric-icon purple"><Clock3 size={18}/></span></div><div className="metric-value window-value">{nextWindow ? formatTime(nextWindow.start, false) : outlookRisk === 'unknown' ? t("Incomplete") : t("None")}{nextWindow && <small>– {formatTime(nextWindow.end, false)}</small>}</div><div className="metric-detail">{nextWindow ? t('{day} · {hours} {unit} of potential overlap', { day: formatDay(nextWindow.start), hours: nextWindow.hours, unit: t(nextWindow.hours === 1 ? 'hour' : 'hours') }) : outlookRisk === 'unknown' ? t("Tide or rain coverage is incomplete") : t("No windows in available forecast")}</div></section></div>
          <div className="outlook-grid">{forecastPanel()}<section className="outlook-card"><div className="outlook-card-heading"><span className="eyebrow">{t("THE NEXT 24 HOURS")}</span><ShieldCheck size={19}/></div><h2>{t("A little context")}<br/>{t("for your coast.")}</h2><div className="risk-scale"><div className={`scale-indicator ${outlookRisk}`}/><span/><span/><span/></div><div className="scale-labels"><span>{t("Low")}</span><span>{t("Elevated")}</span><span>{t("High")}</span></div><Badge risk={outlookRisk}/><p>{outlookRisk === 'unknown' ? t("Part of the forecast is unavailable. Check official advisories before making plans.") : outlookRisk === 'low' ? t("Tide and rain are not forecast to cross your overlap thresholds in the next 24 hours.") : t("Higher tides and rainfall may coincide. Allow extra time and keep low-lying areas in mind.")}</p><button onClick={() => navigate('risk')}>{t("Understand your outlook")} <ArrowRight size={15}/></button><span className="outlook-note">{t("Planning guidance · not a flood prediction")}</span></section></div>
          {dailyForecast}
          <div className="local-grid"><section className="panel map-panel"><PanelHeading title={t("Your stretch of coast")} subtitle={t('{location} · ZIP forecast point and nearby tide reference.', { location: data.location.name })}><span className="map-location-chip"><MapPin size={12}/>{activeZip}</span></PanelHeading><Suspense fallback={<div className="map-loading">{t("Loading your coastline…")}</div>}><LocalMap location={data.location}/></Suspense><div className="map-foot"><span><i/>{t("Weather forecast point")}</span><span><i className="station"/>{t("Tide prediction station")}</span><small>{t("Location reference, not flood extent")}</small></div></section>{preparation()}</div>
        </>}

        {page === 'tides' && <><div className="detail-hero"><div className="detail-hero-icon"><Waves size={35}/></div><div><span className="eyebrow">{data.location.station ? `${data.location.stationName} · NOAA ${data.location.station}` : t("NO NEARBY TIDE STATION")}</span><h2>{t("Follow the highs. Plan for the lows.")}</h2><p>{t("Astronomical tide predictions in feet above Mean Lower Low Water.")}</p></div><div className="detail-stat"><small>{t("Next low tide")}</small><b>{nextLow?.height.toFixed(2) ?? '—'} <span>ft</span></b><small>{nextLow ? formatTime(nextLow.time) : t("Unavailable")}</small></div></div>{forecastPanel('tides', true)}<section className="panel table-panel"><PanelHeading title={t("Upcoming high & low tides")} subtitle={t("NOAA predictions · all times Eastern")}/>{!data.tides.length && <p className="empty-text">{t(data.sources.tides.error ?? "Tide predictions are currently unavailable.")} {t("Rainfall is available on the Rain tab; tide-and-rain overlap remains incomplete.")}</p>}<MobileTideList tides={data.tides.filter(t => Date.parse(t.time) > now).slice(0, 28)} threshold={preferences.tideThreshold}/><div className="table-scroll"><table><thead><tr><th>{t("Date")}</th><th>{t("Time")}</th><th>{t("Tide")}</th><th>{t("Height (ft MLLW)")}</th><th>{t("Your tide threshold")}</th></tr></thead><tbody>{data.tides.filter(t => Date.parse(t.time) > now).slice(0, 28).map(tide => <tr key={tide.time}><td>{formatDay(tide.time)}</td><td>{formatTime(tide.time)}</td><td><span className={`tide-type ${tide.type === 'H' ? 'high' : 'low'}`}>{tide.type === 'H' ? <ArrowUp size={14}/> : <ArrowDown size={14}/>}{tide.type === 'H' ? t("High tide") : t("Low tide")}</span></td><td><b>{tide.height.toFixed(2)} ft</b></td><td>{tide.height >= preferences.tideThreshold ? <span className="threshold-exceeded">{t("Above")} {preferences.tideThreshold.toFixed(1)} ft</span> : t("Below threshold")}</td></tr>)}</tbody></table></div></section><div className="info-note"><Info size={18}/><p>{t("Predictions do not include storm surge, wind setup, sea-level anomalies, or drainage conditions. This station is a prediction location, not a live water-level sensor. Water levels in local canals and lakes may differ.")}</p></div></>}

        {page === 'rainfall' && <><div className="rain-summary"><section className="panel rain-stat"><CloudRain size={25}/><span>{t("Next 24 hours")}</span><b>{rain24?.toFixed(2) ?? '—'} <small>{t("inches")}</small></b><p>{t("Total expected precipitation")}</p></section><section className="panel rain-stat"><Droplets size={25}/><span>{t("Highest rain probability")}</span><b>{next24.some(h => h.chance !== null) ? Math.max(...next24.map(h => h.chance ?? 0)) : '—'}<small>%</small></b><p>{t("Within the next 24 hours")}</p></section><section className="panel rain-stat"><Wind size={25}/><span>{t("Forecast at this hour")}</span><b className="wind-value">{futureHours[0]?.wind ?? '—'}</b><p>{describeWeather(futureHours[0]?.description ?? '')}</p></section></div>{forecastPanel('rain', true)}{dailyForecast}<section className="panel table-panel"><PanelHeading title={t("Hour by hour")} subtitle={t("Rainfall estimates, probability, and coastal context.")}/><MobileHourlyList hours={chartHours.slice(0, 48)} preferences={preferences}/><div className="table-scroll"><table><thead><tr><th>{t("Time (Eastern)")}</th><th>{t("Conditions")}</th><th>{t("Rain chance")}</th><th>{t("Rain amount")}</th><th>{t("Estimated tide")}</th><th>{t("Overlap")}</th></tr></thead><tbody>{chartHours.slice(0, 48).map(h => <tr key={h.time}><td>{formatDay(h.time, { weekday: 'short' })} · {formatTime(h.time)}</td><td><span className="conditions-cell"><WeatherIcon chance={h.chance} size={18}/>{describeWeather(h.description)}</span></td><td>{h.chance ?? '—'}%</td><td>{h.rain?.toFixed(3) ?? '—'} in</td><td>{h.tide?.toFixed(2) ?? '—'} ft</td><td><Badge risk={riskFor(h, preferences)}>{t(riskNames[riskFor(h, preferences)])}</Badge></td></tr>)}</tbody></table></div></section></>}

        {page === 'risk' && <><section className="risk-explainer"><div className="risk-explainer-symbol"><Activity size={30}/></div><div><span className="eyebrow">{t("LOOK FOR THE OVERLAP")}</span><h2>{t("Higher tide + rainfall = a reason to prepare.")}</h2><p>{t("Higher coastal water can slow stormwater drainage. These windows flag when your tide threshold and at least one rain threshold coincide.")}</p></div><button className="button secondary" onClick={() => navigate('settings')}><SlidersHorizontal size={15}/>{t("Adjust thresholds")}</button></section>{forecastPanel('combined', true)}<div className="section-heading"><div><h2>{t("Upcoming overlap windows")}</h2><span>{windows.length} {t("windows across the available seven-day forecast")}</span></div><button className="text-button" onClick={() => setModal('methodology')}><Info size={14}/>{t("How this is calculated")}</button></div><div className="windows-grid">{windows.length ? windows.map((w, i) => <WindowCard key={w.start} window={w} index={i} onPrepare={() => navigate('prepare')}/>) : <div className="panel empty-windows"><ShieldCheck size={32}/><h3>{t("No overlap windows detected")}</h3><p>{outlookRisk === 'unknown' ? t("Some forecasts are missing. This does not confirm low risk; review the data status and official advisories.") : t("The available tide and rain forecasts do not cross your current thresholds together.")}</p></div>}</div><div className="info-note"><Info size={18}/><p>{t("An overlap score is a planning indicator, not a flood probability or a forecast of flood depth. Elevation, seawalls, drainage, groundwater, recent rainfall, and wind also matter. Follow official advisories.")}</p></div>{preparation()}</>}

        {page === 'calendar' && activeZip !== DEFAULT_ZIP && <div className="info-note"><Info size={18}/><p>{t("This seasonal calendar is published by the City of Hollywood. It is a Hollywood reference, not a king tide calendar for ZIP")} {activeZip}{t(". Use the Tides tab for your selected station’s predictions.")}</p></div>}
        {page === 'calendar' && <KingCalendar now={now} days={activeZip === DEFAULT_ZIP ? days : []} onSelect={key => { setSelectedDay(key); setPage('overview'); location.hash = 'overview'; }}/>}

        {page === 'prepare' && <><section className="prepare-hero"><span className="prepare-hero-icon"><LifeBuoy size={42}/></span><div><span className="eyebrow">{t("A CALMER COAST STARTS AT HOME")}</span><h2>{t("Know your next step before you need it.")}</h2><p>{t("Use this checklist before a tide-and-rain overlap window. Start early, stay informed, and look out for your neighbors.")}</p></div></section><div className="prepare-grid">{preparation(true)}<section className="panel resources-panel"><PanelHeading title={t("Keep the right information close")} subtitle={t("Hollywood resources and nationwide weather guidance.")}/><a href="https://www.hollywoodfl.org/1473/King-Tides-and-High-Tides" target="_blank" rel="noreferrer"><span className="resource-icon"><Waves size={20}/></span><span><b>{t("Hollywood king tides")}</b><small>{t("Local tide guidance and flood preparation")}</small></span><ArrowUpRight size={16}/></a><a href={data ? `https://forecast.weather.gov/MapClick.php?lat=${data.location.lat}&lon=${data.location.lon}` : 'https://www.weather.gov/'} target="_blank" rel="noreferrer"><span className="resource-icon"><CloudRain size={20}/></span><span><b>{t("NWS forecast for your ZIP")}</b><small>{t("Official forecasts and active warnings")}</small></span><ArrowUpRight size={16}/></a><a href="https://www.hollywoodfl.org/103/Stormwater" target="_blank" rel="noreferrer"><span className="resource-icon"><Droplets size={20}/></span><span><b>{t("Hollywood stormwater")}</b><small>{t("Drainage and stormwater information")}</small></span><ArrowUpRight size={16}/></a><div className="safety-note"><TriangleAlert size={20}/><h3>{t("Turn around, don’t drown.")}</h3><p>{t("Avoid walking or driving through floodwater. Depth and road conditions can be difficult to judge. In an emergency, call 911.")}</p></div></section></div><section className="panel official-alerts"><PanelHeading title={t("Current official weather alerts")} subtitle={t("National Weather Service · forecast point in selected ZIP")}/>{data.sources.alerts.status === 'unavailable' ? <p className="empty-text">{t("Alert data is unavailable. Check NWS directly for active warnings.")}</p> : data.alerts.length ? data.alerts.map(a => <button key={a.id} className="official-alert-item" onClick={() => openAdvisory(a)}><TriangleAlert size={19}/><span><b>{a.event}</b><small>{a.expires ? t('Expires {day} at {time}', { day: formatDay(a.expires), time: formatTime(a.expires) }) : t("Check advisory for expiration")}</small></span><ArrowUpRight size={17}/></button>) : <p className="empty-text">{t("No active NWS alerts returned for this forecast point.")}</p>}</section></>}

        {page === 'settings' && <><section className="panel settings-panel"><PanelHeading title={t("Planning preferences")} subtitle={t("Tailor the outlook to your experience with local tides and rain.")}/>{settingsForm}</section><section className="panel data-panel"><PanelHeading title={t("Location & data")} subtitle={t("The local points behind your forecast.")}/><div className="location-details"><span><MapPin size={18}/><b>{data.location.name}</b><small>{"ZIP"} {activeZip} · {data.location.lat.toFixed(3)}°, {data.location.lon.toFixed(3)}°</small></span><span><Waves size={18}/><b>{data.location.station ? t('NOAA station {station}', { station: data.location.station }) : t("No nearby tide station")}</b><small>{data.location.stationName ?? t("No NOAA prediction point within 25 km")}{data.location.stationDistanceKm !== null && t(' · {distance} km from forecast point', { distance: data.location.stationDistanceKm })}</small></span><span><CloudRain size={18}/><b>{t("National Weather Service")}</b><small>{t("Forecast grid for the selected ZIP point")}</small></span></div><p>{t("Preferences, checklist progress, and notification history are stored only in this browser, separately for each ZIP. Other browsers and devices have their own preferences. People sharing this browser profile share its saved preferences. Notification checks run while the page is open; this app does not send SMS or email.")}</p><button className="text-button" onClick={() => setModal('methodology')}>{t("Read about the methodology")} <ArrowRight size={14}/></button></section></>}

        <footer className="data-footer"><div className="data-footer-top"><div className="source-summary"><span className="source-brand"><Waves size={14}/></span><span>{t("Grounded in trusted data")}</span><a href={data.location.station ? `https://tidesandcurrents.noaa.gov/stationhome.html?id=${data.location.station}` : 'https://tidesandcurrents.noaa.gov/tide_predictions'} target="_blank" rel="noreferrer">NOAA <ExternalLink size={10}/></a><span className="footer-dot">·</span><a href="https://www.weather.gov/documentation/services-web-api" target="_blank" rel="noreferrer">{t("National Weather Service")} <ExternalLink size={10}/></a></div><div className="data-actions"><button onClick={exportForecast}><Download size={13}/>{t("Export forecast")}</button><button onClick={() => void refresh()} disabled={loading}><RefreshCw size={13} className={loading ? 'spin' : ''}/>{loading ? t("Refreshing") : t("Refresh")}</button></div></div><div className="source-statuses">{Object.entries(data.sources).map(([key, s]) => <span key={key}><i className={s.status}/><b>{key === 'tides' ? t("Tides") : key === 'weather' ? t("Weather") : t("Advisories")}:</b> {t(s.status)}{s.fetchedAt && t(' · fetched {time}', { time: formatTime(s.fetchedAt) })}{s.issuedAt && t(' · issued {day} {time}', { day: formatDay(s.issuedAt), time: formatTime(s.issuedAt) })}{s.note && ` · ${t(s.note)}`}</span>)}</div><p>{t("For awareness and preparation. Tide-and-rain overlap does not predict flood depth or guarantee flooding. Follow official warnings.")} <button onClick={() => setModal('methodology')}>{t("About the data")}</button></p></footer>
        </>}
      </main>
    </div>
    <nav className="mobile-tabbar" aria-label={t("Mobile primary navigation")}>
      {navItems.filter(item => item.id !== 'calendar').map(item => <a key={item.id} href={`#${item.id}`} onClick={event => navigateLink(event, item.id)} aria-label={t(item.name)} aria-current={page === item.id ? 'page' : undefined} className={page === item.id ? 'active' : ''}><item.icon size={22} aria-hidden="true"/><span>{t(mobileNames[item.id])}</span></a>)}
      <button className={['calendar', 'prepare', 'settings'].includes(page) || mobileNav ? 'active' : ''} onClick={() => setMobileNav(true)} aria-label={t("More navigation")} aria-haspopup="dialog" aria-expanded={mobileNav}><Menu size={22} aria-hidden="true"/><span>{t("More")}</span></button>
    </nav>
    <dialog ref={menuDialog} className="app-dialog menu-dialog" aria-labelledby="menu-title" onCancel={() => setMobileNav(false)} onClick={event => { if (event.target === event.currentTarget) setMobileNav(false); }}>
      <div className="dialog-content"><div className="dialog-heading"><span className="eyebrow">{data?.location.name ?? t("Forecast location")} · {activeZip}</span><button className="icon-button" onClick={() => setMobileNav(false)} aria-label={t("Close navigation")}><X size={23}/></button></div><h2 id="menu-title">{t("A little more for your coast.")}</h2>
        <nav className="more-navigation" aria-label={t("More navigation options")}>
          {[{ id: 'calendar', name: t("King tide calendar"), text: t("See the seasonal higher tides"), icon: CalendarDays }, { id: 'prepare', name: t("Preparation guide"), text: t("Your household checklist & resources"), icon: ShieldCheck }, { id: 'settings', name: t("Settings & alerts"), text: t("Adjust thresholds & notifications"), icon: Settings2 }].map(item => <a key={item.id} href={`#${item.id}`} onClick={event => navigateLink(event, item.id as Page)} aria-current={page === item.id ? 'page' : undefined}><span className="more-icon"><item.icon size={22} aria-hidden="true"/></span><span><b>{t(item.name)}</b><small>{t(item.text)}</small></span><ChevronRight size={18} aria-hidden="true"/></a>)}
        </nav><p className="more-note">{t("Local tides. Local forecasts. A clearer view of what’s ahead.")}</p>
      </div>
    </dialog>
    <dialog ref={dialog} className={`app-dialog ${modal === 'alerts' ? 'alert-drawer' : ''}`} aria-label={modal === 'alerts' ? t("Alert preferences") : modal === 'advisory' ? t("Official weather advisory") : t("Forecast methodology")} onCancel={() => setModal(null)} onClick={e => { if (e.target === e.currentTarget) setModal(null); }}><div className="dialog-content"><div className="dialog-heading"><span className="eyebrow">{modal === 'alerts' ? t("STAY ONE STEP AHEAD") : modal === 'advisory' ? t("NATIONAL WEATHER SERVICE") : t("BEHIND YOUR OUTLOOK")}</span><button className="icon-button" onClick={() => setModal(null)} aria-label={t("Close dialog")}><X size={21}/></button></div>
      {modal === 'alerts' && <><h2>{t("Your alerts, your way.")}</h2><p className="dialog-intro">{t("Keep the tide-and-rain windows that matter on your radar.")}</p>{settingsForm}<div className="drawer-advisories"><h3>{t("Official weather advisories")} <span>{data?.alerts.length ?? 0}</span></h3>{data?.alerts.map(a => <button key={a.id} className="official-alert-item" onClick={() => openAdvisory(a)}><TriangleAlert size={17}/><span><b>{a.event}</b><small>{a.expires ? t('Until {day} {time}', { day: formatDay(a.expires), time: formatTime(a.expires) }) : t("See advisory details")}</small></span><ArrowUpRight size={16}/></button>)}{data?.sources.alerts.status === 'unavailable' && <p>{t("Alerts are unavailable; check the NWS website directly.")}</p>}{data?.sources.alerts.status !== 'unavailable' && !data?.alerts.length && <p>{t("No active NWS advisories returned for this location.")}</p>}</div></>}
      {modal === 'methodology' && <><h2>{t("A clearer view, with clear limits.")}</h2><p className="dialog-intro">{t("Tidewatch connects two forecasts to make coastal planning easier.")}</p><div className="method-section"><Waves size={23}/><div><h3>{t("Tide predictions")}</h3><p>{data?.location.station ? t('NOAA’s {stationName} station ({station}) provides predicted high and low tides, {distance} km from the forecast point.', { stationName: data.location.stationName ?? '', station: data.location.station, distance: data.location.stationDistanceKm ?? '—' }) : t("No NOAA prediction station was found within 25 km of the forecast point.")} {t("The nearest station is a reference; tides can differ across waterways. Heights use feet above Mean Lower Low Water (MLLW), a tidal datum, not the elevation of your street. The chart uses a cosine curve between those points; intermediate heights are estimates.")}</p><a href="https://api.tidesandcurrents.noaa.gov/api/prod/" target="_blank" rel="noreferrer">{t("NOAA API documentation")} <ArrowUpRight size={12}/></a></div></div><div className="method-section"><CloudRain size={23}/><div><h3>{t("Precipitation forecasts")}</h3><p>{t("NWS hourly forecasts provide rain probability and weather conditions for the selected ZIP’s forecast point. Rain amounts come from the gridded quantitative precipitation forecast, in millimeters converted to inches. Amounts are divided evenly over each forecast interval; exact within-interval rain timing is uncertain. Where NWS hourly text is unavailable, including marine forecast points, rain probability, temperature, and wind use NWS gridded forecast intervals. This fallback is labeled in the data status. Missing data remains unknown.")}</p></div></div><div className="method-section"><Activity size={23}/><div><h3>{t("Overlap potential")}</h3><p>{t('Elevated means estimated tide is at least your threshold ({tide} ft) and either hourly rain is at least {rain} in or probability is at least {chance}%. High means tide exceeds that threshold by 0.4 ft and rain is at least {highRain} in or probability is at least {highChance}%. These rules are adjustable planning heuristics, not calibrated flood probabilities.', { tide: preferences.tideThreshold.toFixed(1), rain: preferences.rainThreshold.toFixed(2), chance: preferences.chanceThreshold, highRain: Math.max(preferences.rainThreshold, 0.08).toFixed(2), highChance: Math.max(preferences.chanceThreshold, 60) })}</p></div></div><div className="method-section"><Clock3 size={23}/><div><h3>{t("Timing & freshness")}</h3><p>{t('All displayed times use {zone}, including daylight saving time. The app refreshes every ten minutes. Cached data is labeled with its retrieval time; forecasts outside available coverage are incomplete. Browser notifications run only while this page is open.', { zone: TIME_ZONE })}</p></div></div><div className="info-note"><Info size={18}/><p>{t("Flooding depends on local drainage, groundwater, elevation, recent rain, wind, and surge. This app does not model these factors or map flood extents.")}</p></div></>}
      {modal === 'advisory' && advisory && <><span className="official-label"><TriangleAlert size={16}/>{t('{severity} severity', { severity: t(advisory.severity) })}</span><h2 lang="en">{advisory.event}</h2>{language === 'es' && <p className="advisory-language-note">{t('Official NWS advisory text is provided in English.')}</p>}<p className="dialog-intro" lang="en">{advisory.headline}</p><div className="advisory-times"><Clock3 size={15}/>{t("Expires")} {advisory.expires ? t('{day} at {time}', { day: formatDay(advisory.expires), time: formatTime(advisory.expires) }) : t("not specified")}</div><p className="advisory-description" lang="en">{advisory.description}</p>{advisory.instruction && <div className="advisory-instructions"><h3>{t("Recommended action")}</h3><p lang="en">{advisory.instruction}</p></div>}<a className="button primary" href={data ? `https://forecast.weather.gov/MapClick.php?lat=${data.location.lat}&lon=${data.location.lon}` : 'https://www.weather.gov/'} target="_blank" rel="noreferrer">{t("View official NWS updates")} <ExternalLink size={14}/></a></>}
    </div></dialog>
    {toast && <div className="toast" role="status"><CheckCircle2 size={17}/>{t(toast)}<button onClick={() => setToast('')} aria-label={t("Dismiss notification")}><X size={15}/></button></div>}
  </div>;
}

function WindowCard({ window: w, index, onPrepare }: { window: RiskWindow; index: number; onPrepare: () => void }) {
  const { t, formatDay, formatTime } = useLanguage();
  return <section className="panel window-card"><div className="window-card-top"><span className="window-number">{String(index + 1).padStart(2, '0')}</span><Badge risk={w.risk}/></div><span className="window-date">{formatDay(w.start)}</span><h3>{formatTime(w.start)} <span>–</span> {formatTime(w.end)}</h3><div className="window-stats"><span><Waves size={16}/><b>{w.maxTide.toFixed(2)} ft</b><small>{t("estimated peak")}</small></span><span><CloudRain size={16}/><b>{w.rain?.toFixed(2) ?? '—'} in</b><small>{t("window rainfall")}</small></span><span><Droplets size={16}/><b>{w.chance ?? '—'}%</b><small>{t("peak rain chance")}</small></span></div><button className="text-button" onClick={onPrepare}>{t("Prepare for this window")} <ArrowRight size={14}/></button></section>;
}

const calendarRiskNames: Record<Risk, string> = { low: 'Low', moderate: 'Elev.', high: 'High', unknown: 'Gap' };
const kingPeriods2026 = [ ['2026-08-11', '2026-08-14'], ['2026-09-09', '2026-09-13'], ['2026-09-26', '2026-10-01'], ['2026-10-07', '2026-10-13'], ['2026-10-24', '2026-10-31'], ['2026-11-05', '2026-11-11'], ['2026-11-22', '2026-11-28'], ['2026-12-05', '2026-12-08'], ['2026-12-23', '2026-12-27'] ];
function KingCalendar({ now, days, onSelect }: { now: number; days: { key: string; risk: Risk }[]; onSelect: (key: string) => void }) {
  const { t, formatDay, locale } = useLanguage();
  const today = dayKey(new Date(now));
  const [month, setMonth] = useState(() => { const parts = today.split('-'); return new Date(Number(parts[0]), Number(parts[1]) - 1, 1, 12); });
  const year = month.getFullYear(), m = month.getMonth();
  const cells = Array.from({ length: Math.ceil((new Date(year, m, 1).getDay() + new Date(year, m + 1, 0).getDate()) / 7) * 7 }, (_, i) => {
    const d = i - new Date(year, m, 1).getDay() + 1;
    return d > 0 && d <= new Date(year, m + 1, 0).getDate() ? { day: d, key: `${year}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}` } : null;
  });
  const upcoming = kingPeriods2026.filter(([, end]) => end >= today);
  return <><div className="calendar-grid"><section className="panel calendar-panel"><PanelHeading title={month.toLocaleDateString(locale, { month: 'long', year: 'numeric' })} subtitle={t("Seasonal awareness, one day at a time.")}><div className="calendar-nav"><button className="icon-button" aria-label={t("Previous month")} onClick={() => setMonth(new Date(year, m - 1, 1, 12))}><ChevronLeft size={19}/></button><button className="text-button" onClick={() => { const p = today.split('-'); setMonth(new Date(Number(p[0]), Number(p[1]) - 1, 1, 12)); }}>{t("Today")}</button><button className="icon-button" aria-label={t("Next month")} onClick={() => setMonth(new Date(year, m + 1, 1, 12))}><ChevronRight size={19}/></button></div></PanelHeading><div className="calendar-weekdays">{[t("Sun"), t("Mon"), t("Tue"), t("Wed"), t("Thu"), t("Fri"), t("Sat")].map(d => <span key={d}>{d}</span>)}</div><div className="calendar-cells">{cells.map((cell, i) => { const king = cell && kingPeriods2026.some(([s, e]) => cell.key >= s && cell.key <= e); const forecast = days.find(d => d.key === cell?.key); return <button key={cell?.key ?? `empty-${i}`} disabled={!cell || !forecast} className={`calendar-cell ${king ? 'king' : ''} ${cell?.key === today ? 'today' : ''} ${!cell ? 'blank' : ''}`} onClick={() => cell && onSelect(cell.key)} aria-label={cell ? `${cell.key}${king ? t(", seasonal king tide period") : ''}${forecast ? t(', {risk} overlap, view forecast', { risk: t(riskNames[forecast.risk]) }) : t(", weather forecast not yet available")}` : undefined}>{cell && <><b>{cell.day}</b>{king && <span><Waves size={12}/>{t("King")}</span>}{forecast && <small className={forecast.risk}><i/>{t(calendarRiskNames[forecast.risk])}</small>}</>}</button>; })}</div><div className="calendar-legend"><span><i/>{t("Seasonal king tide period")}</span><span><span className="today-dot"/>{t("Today")}</span><small>{t("Select a day within the forecast horizon.")}</small></div></section><section className="panel king-upcoming"><span className="icon-surface"><CalendarDays size={23}/></span><h2>{t("Mark the higher tides.")}</h2><p>{t("City of Hollywood’s published 2026 seasonal windows. Peaks vary by location.")}</p><div className="king-periods">{upcoming.length ? upcoming.map(([start, end]) => <div key={start}><span><Waves size={16}/></span><div><b>{formatDay(`${start}T12:00:00-04:00`, { month: 'short', day: 'numeric' })} – {formatDay(`${end}T12:00:00-04:00`, { month: 'short', day: 'numeric' })}</b><small>{start <= today && end >= today ? t("Current seasonal window") : t("Upcoming seasonal window")}</small></div></div>) : <p>{t("No remaining 2026 windows. Check the city website for next season’s calendar.")}</p>}</div><a className="text-button" href="https://www.hollywoodfl.org/1473/King-Tides-and-High-Tides" target="_blank" rel="noreferrer">{t("City of Hollywood calendar")} <ArrowUpRight size={14}/></a></section></div><div className="info-note"><Info size={18}/><p>{t("Seasonal dates indicate potentially higher astronomical tides, not a rain forecast or a confirmed flooding event. Rainfall and overlap forecasts are available only within the current seven-day horizon. The city’s published schedule currently covers 2026.")}</p></div></>;
}
